// Import the workflow helper module
const telegram = require('./telegram-bot-workflow.js');

// Get webhook data
const webhookData = $input.all()[0].json;

// Initialize database connection (adjust based on your DB)
// const db = new telegram.DatabaseHelper($('Postgres').getConnection());

// For this example, we'll mock the database
const mockDB = {
  async executeQuery(query, params) {
    console.log('Mock DB Query:', query, params);
    return [];
  },
  async insertDraft(userId, content) {
    console.log('Insert draft:', userId, content);
    return Math.floor(Math.random() * 1000);
  },
  async getDrafts(userId, page, limit) {
    return {
      drafts: [
        { id: 1, content: 'Draft 1', status: 'pending', created_at: new Date() },
        { id: 2, content: 'Draft 2', status: 'pending', created_at: new Date() }
      ],
      total: 2,
      hasMore: false,
      currentPage: 1,
      totalPages: 1
    };
  },
  async updateDraft(draftId, content, status) {
    console.log('Update draft:', draftId, content, status);
    return true;
  },
  async deleteDraft(draftId, userId) {
    console.log('Delete draft:', draftId, userId);
    return true;
  }
};

// Process the webhook
try {
  const response = await telegram.handleTelegramWebhook(webhookData, mockDB);
  return [{ json: response }];
} catch (error) {
  console.error('Handler error:', error);
  return [{
    json: {
      method: 'sendMessage',
      chat_id: webhookData.message?.chat?.id || webhookData.callback_query?.message?.chat?.id,
      text: '❌ Erro ao processar sua mensagem. Tente novamente.'
    }
  }];
}
